package com.queuex.api.controller; import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> missing(Exception e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}@ExceptionHandler(IllegalStateException.class) ResponseEntity<?> state(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}}
